 {id:'A7',name:'La séptima',f:[0,1,0,0],level:2,desc:'Un solo dedo'},{id:'D',name:'Re',f:[2,2,2,0],level:2,desc:'Tres cuerdas juntas'},{id:'D7',name:'Re séptima',f:[2,2,2,3],level:3,desc:'Para más adelante'},{id:'Em',name:'Mi menor',f:[0,4,3,2],level:3,desc:'Cambio de tres dedos'},
 {id:'E7',name:'Mi séptima',f:[1,2,0,2],level:3,desc:'Sonido muy blues'},{id:'Bb',name:'Si bemol',f:[3,2,1,1],level:3,desc:'Introduce la cejilla'},{id:'A',name:'La',f:[2,1,0,0],level:2,desc:'Otro básico'},{id:'Gm',name:'Sol menor',f:[0,2,3,1],level:3,desc:'Color menor'}
